DROP FUNCTION IF EXISTS count_non_working_days;
CREATE OR REPLACE FUNCTION count_non_working_days(start_date DATE, end_date DATE)
RETURNS INT AS $$
DECLARE
  day_count INT := 0;
BEGIN
  FOR current_date IN start_date..end_date LOOP
    IF EXTRACT(DOW FROM current_date) = 0 OR EXTRACT(DOW FROM current_date) = 6 THEN -- Saturday or Sunday
      day_count := day_count + 1;
    END IF;
    IF EXISTS(SELECT 1 FROM holidays WHERE holiday_date = current_date) THEN -- Holiday
      day_count := day_count + 1;
    END IF;
  END LOOP;
  RETURN day_count;
END;
$$ LANGUAGE plpgsql;

